<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Review order · MediServe</title><style>*{box-sizing:border-box}body{margin:0;background:#f7faf8;color:#18332c;font:15px/1.5 system-ui,sans-serif}.top{background:#073d31;color:#eafff7;text-align:center;padding:8px;font-size:12px}.wrap{width:min(900px,calc(100% - 32px));margin:auto}.head{background:#fff;border-bottom:1px solid #e6eeeb}.headin{height:68px;display:flex;align-items:center;justify-content:space-between}.brand{font-size:23px;font-weight:850;color:#087f5b;text-decoration:none}.brand span{color:#18332c}a{color:#087f5b}.title{margin:30px 0 18px}.title h1{margin:0;font-size:29px}.steps{margin-bottom:20px;color:#087f5b;font-size:13px;font-weight:700}.cols{display:grid;grid-template-columns:1fr 300px;gap:16px}.panel{background:#fff;border:1px solid #e6eeeb;border-radius:15px;padding:21px}.panel h2{margin:0 0 14px;font-size:18px}.address{white-space:pre-line;color:#53645e}.item{display:flex;justify-content:space-between;gap:14px;padding:12px 0;border-bottom:1px solid #edf2ef}.item:last-child{border-bottom:0}.summary{display:flex;justify-content:space-between;padding:9px 0}.total{border-top:1px solid #e6eeeb;margin-top:8px;padding-top:15px;font-size:18px;font-weight:800}.btn{display:block;margin-top:16px;text-align:center;padding:12px;border-radius:9px;background:#087f5b;color:#fff;text-decoration:none;font-weight:750}.btn:hover{background:#05684b}.muted{color:#70817c;font-size:13px}@media(max-width:680px){.cols{grid-template-columns:1fr}.panel{padding:17px}}</style></head><body><div class="top">Your health essentials, delivered with care · Secure mobile OTP</div><header class="head"><div class="wrap headin"><a class="brand" href="{{ route('home') }}">medi<span>Serve</span></a><a href="{{ route('cart.index') }}">Back to cart</a></div></header><main class="wrap"><div class="title"><h1>Review your order</h1><p>Make sure the delivery address and items are correct.</p></div><div class="steps">1. Delivery address　✓　→　2. Review order　→　3. Payment</div><div class="cols"><section><div class="panel"><h2>Delivering to</h2><strong>{{ $address->label }} · {{ $address->recipient_name }}</strong><p class="address">{{ $address->mobile }}<br>{{ $address->address_line }}<br>{{ $address->pincode }}@if($address->latitude && $address->longitude)<br><span class="muted">Pinned location: {{ $address->latitude }}, {{ $address->longitude }}</span>@endif</p><a href="{{ route('checkout') }}">Change address</a></div><div class="panel" style="margin-top:15px"><h2>Order items</h2>@foreach($items as $item)<div class="item"><span><strong>{{ $item->name }}</strong><br><span class="muted">Qty {{ $item->quantity }}</span></span><strong>{{ $item->price !== null ? '₹'.number_format((float)$item->price * $item->quantity, 2) : 'Price pending' }}</strong></div>@endforeach</div></section><aside class="panel"><h2>Order total</h2><div class="summary"><span>Items subtotal</span><strong>₹{{ number_format($subtotal,2) }}</strong></div><div class="summary"><span>Delivery</span><strong>Free</strong></div><div class="summary total"><span>Total</span><span>₹{{ number_format($subtotal,2) }}</span></div><p class="muted">You will choose your payment method on the next screen.</p><a class="btn" href="{{ route('checkout.payment') }}">Continue to payment</a></aside></div></main></body></html>
